/* ============================================================
   Paleta — tema "papel de cartório" (pergaminho, tinta, selos)
   ============================================================ */
const COLORS = {
  bg: "#F2ECE0",
  bgPanel: "#FBF8F1",
  ink: "#2E2418",
  inkSoft: "#6B5D4A",
  line: "#C9BBA0",
  lineDark: "#8A7860",
  accent: "#8C3B2E", // selo/lacre vermelho
  gold: "#A8863B",
};

const STATUS_META = {
  confirmado: { cor: "#3F6B4A", label: "Confirmado" },
  estimado: { cor: "#A8863B", label: "Estimado" },
  grafia_variante: { cor: "#4A6FA5", label: "Grafia variante" },
  divergente: { cor: "#C1651F", label: "Divergente" },
  incompleto: { cor: "#9B9384", label: "Incompleto" },
  contestado: { cor: "#8C3B2E", label: "Contestado" },
};

function corPrincipal(statusList) {
  if (!statusList || statusList.length === 0) return STATUS_META.incompleto.cor;
  const prioridade = ["contestado", "divergente", "grafia_variante", "estimado", "confirmado", "incompleto"];
  for (const s of prioridade) {
    if (statusList.includes(s)) return STATUS_META[s].cor;
  }
  return STATUS_META.incompleto.cor;
}

/* ============================================================
   Layout hierárquico
   Cada "unidade familiar" = uma pessoa de sangue + seus cônjuges,
   posicionada por geração (linha) e ordenada por índice de descoberta
   dentro do ramo do pai.
   ============================================================ */
const DEFAULT_NODE_W = 168;
const NODE_H = 64;
const DEFAULT_H_GAP = 28;
const DEFAULT_V_GAP = 110;
const DEFAULT_COUPLE_GAP = 14;

function buildIndex(pessoas) {
  const byId = new Map();
  pessoas.forEach((p) => byId.set(p.id, p));
  return byId;
}

// Determina as "raízes" (pessoas sem pai nem mãe registrados)
function findRoots(pessoas, byId) {
  const comPais = new Set();
  pessoas.forEach((p) => {
    (p.filhos_ids || []).forEach((fid) => comPais.add(fid));
  });
  return pessoas.filter((p) => !comPais.has(p.id) && p.geracao === p.geracao.toUpperCase());
}

function App() {
  const pessoas = PESSOAS_RAW;
  const byId = useMemo(() => buildIndex(pessoas), [pessoas]);
  const roots = useMemo(() => findRoots(pessoas, byId), [pessoas, byId]);

  // Nós recolhidos (descendência oculta). Por padrão, colapsa tudo exceto
  // a linha direta até Rodrigo, para não abrir com 489 pessoas na tela.
  const LINHA_DIRETA = useMemo(() => {
    const linha = new Set([
      "B-gaetano",
      "C-giovanni-1888",
      "D-mario",
      "E-iracema",
      "F-shirley-aroni",
      "G-rodrigo-aroni-siquette",
    ]);
    return linha;
  }, []);

  const [collapsed, setCollapsed] = useState(() => {
    const s = new Set();
    pessoas.forEach((p) => {
      if ((p.filhos_ids || []).length > 0 && !LINHA_DIRETA.has(p.id)) {
        s.add(p.id);
      }
    });
    return s;
  });

  const [selectedId, setSelectedId] = useState(null);
  const [query, setQuery] = useState("");
  const [showLegend, setShowLegend] = useState(true);
  const [showConfig, setShowConfig] = useState(false);
  const containerRef = useRef(null);
  const [transform, setTransform] = useState({ x: 40, y: 40, k: 1 });
  const dragState = useRef(null);

  // Configuração de layout — controlável pelo painel de ajustes.
  // NODE_W/H_GAP/V_GAP/COUPLE_GAP abaixo são derivados deste estado
  // e usados no cálculo de posição e na renderização SVG.
  const [layoutConfig, setLayoutConfig] = useState({
    nodeW: DEFAULT_NODE_W,
    hGap: DEFAULT_H_GAP,
    vGap: DEFAULT_V_GAP,
    coupleGap: DEFAULT_COUPLE_GAP,
  });
  const NODE_W = layoutConfig.nodeW;
  const H_GAP = layoutConfig.hGap;
  const V_GAP = layoutConfig.vGap;
  const COUPLE_GAP = layoutConfig.coupleGap;

  const toggleCollapse = useCallback((id) => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  // Abre todos os ramos de uma vez (nenhum nó fica recolhido)
  const expandAll = useCallback(() => {
    setCollapsed(new Set());
  }, []);

  // Fecha todos os ramos que têm filhos (volta ao estado mais compacto possível)
  const collapseAll = useCallback(() => {
    setCollapsed(() => {
      const s = new Set();
      pessoas.forEach((p) => {
        if ((p.filhos_ids || []).length > 0) s.add(p.id);
      });
      return s;
    });
  }, [pessoas]);

  /* --------- Construção da lista de nós visíveis + posições --------- */
  const { positioned, edges, generationLabels } = useMemo(() => {
    const visited = new Set();
    const nodesByGen = new Map(); // geracao (letra maiuscula) -> array de {person, x}
    const positioned = new Map(); // id -> {x, y, person}
    const edges = [];

    function generationIndex(letra) {
      return letra.toUpperCase().charCodeAt(0) - 65; // A=0, B=1...
    }

    // Percorre a partir das raízes, em ordem, atribuindo colunas
    let cursorX = 0;

    function layoutPerson(person, depth) {
      if (visited.has(person.id)) return positioned.get(person.id)?.x ?? cursorX;
      visited.add(person.id);

      const genIdx = generationIndex(person.geracao);
      const isCollapsed = collapsed.has(person.id);

      // cônjuges (mesma linha, ao lado)
      const conjugeIds = (person.conjuges || []).filter((cid) => byId.has(cid));

      let childXs = [];
      if (!isCollapsed) {
        (person.filhos_ids || []).forEach((fid) => {
          const filho = byId.get(fid);
          if (filho && !visited.has(fid)) {
            const x = layoutPerson(filho, depth + 1);
            childXs.push(x);
          } else if (filho && visited.has(fid)) {
            const existing = positioned.get(fid);
            if (existing) childXs.push(existing.x);
          }
        });
      }

      let myX;
      if (childXs.length > 0) {
        const media = (Math.min(...childXs) + Math.max(...childXs)) / 2;
        // Se a média dos filhos cair "atrás" do que já está ocupado por
        // outros ramos já processados (ex: um ramo-irmão anterior avançou
        // o cursor além deste ponto), usa o cursor em vez da média - isso
        // evita que este nó (e seus cônjuges) sobreponham nós de ramos
        // adjacentes já posicionados.
        myX = Math.max(media, cursorX);
      } else {
        myX = cursorX;
      }
      cursorX = myX + NODE_W + H_GAP;

      const y = genIdx * V_GAP;
      positioned.set(person.id, { x: myX, y, person, depth });

      // posiciona cônjuges ao lado
      let offset = NODE_W + COUPLE_GAP;
      conjugeIds.forEach((cid) => {
        if (!positioned.has(cid)) {
          const conjuge = byId.get(cid);
          positioned.set(cid, { x: myX + offset, y, person: conjuge, depth, isSpouse: true });
          visited.add(cid);
          offset += NODE_W + COUPLE_GAP;
        }
      });

      // Reserva também o espaço ocupado pelos cônjuges à direita deste nó,
      // avançando o cursor global além deles - sem isso, o próximo ramo
      // processado (irmão ou tio) poderia sobrepor os nós de cônjuge.
      if (offset > NODE_W + COUPLE_GAP) {
        const direitaOcupada = myX + offset - COUPLE_GAP;
        cursorX = Math.max(cursorX, direitaOcupada + H_GAP);
      }

      if (!nodesByGen.has(genIdx)) nodesByGen.set(genIdx, []);
      nodesByGen.get(genIdx).push(person.id);

      // arestas para filhos (se não colapsado)
      if (!isCollapsed) {
        (person.filhos_ids || []).forEach((fid) => {
          if (byId.has(fid)) {
            edges.push({ from: person.id, to: fid, fromSpouse: false });
          }
        });
      }

      return myX;
    }

    roots
      .slice()
      .sort((a, b) => a.nome.localeCompare(b.nome))
      .forEach((r) => layoutPerson(r, 0));

    // Rótulos de geração
    const generationLabels = [];
    const genNames = {
      0: "Geração A",
      1: "Geração B",
      2: "Geração C",
      3: "Geração D",
      4: "Geração E",
      5: "Geração F",
      6: "Geração G",
    };
    nodesByGen.forEach((_, idx) => {
      generationLabels.push({ idx, y: idx * V_GAP, label: genNames[idx] || `Geração ${idx}` });
    });

    return { positioned, edges, generationLabels };
  }, [pessoas, byId, roots, collapsed, layoutConfig]);

  /* --------- Busca --------- */
  const searchResults = useMemo(() => {
    if (!query || query.trim().length < 2) return [];
    const q = query.trim().toLowerCase();
    return pessoas.filter((p) => p.nome.toLowerCase().includes(q)).slice(0, 12);
  }, [query, pessoas]);

  // Expande todos os ancestrais de um nó para garantir visibilidade
  const revealPath = useCallback(
    (id) => {
      setCollapsed((prev) => {
        const next = new Set(prev);
        let current = byId.get(id);
        const guard = new Set();
        while (current) {
          if (guard.has(current.id)) break;
          guard.add(current.id);
          // encontra o pai (quem lista este id em filhos_ids)
          const parent = pessoas.find((p) => (p.filhos_ids || []).includes(current.id));
          if (parent) {
            next.delete(parent.id);
            current = parent;
          } else {
            current = null;
          }
        }
        return next;
      });
      setSelectedId(id);
    },
    [byId, pessoas]
  );

  const bounds = useMemo(() => {
    let minX = Infinity,
      maxX = -Infinity,
      maxY = 0;
    positioned.forEach(({ x, y }) => {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x + NODE_W);
      maxY = Math.max(maxY, y);
    });
    if (!isFinite(minX)) return { minX: 0, maxX: 800, maxY: 400 };
    return { minX, maxX, maxY };
  }, [positioned]);

  const svgWidth = Math.max(1200, bounds.maxX - bounds.minX + 200);
  const svgHeight = bounds.maxY + V_GAP + 100;

  /* --------- Pan/zoom simples --------- */
  const onWheel = useCallback((e) => {
    e.preventDefault();
    setTransform((t) => {
      const delta = -e.deltaY * 0.001;
      const k = Math.min(2.2, Math.max(0.25, t.k + delta));
      return { ...t, k };
    });
  }, []);

  const onMouseDown = useCallback(
    (e) => {
      dragState.current = { startX: e.clientX, startY: e.clientY, origX: transform.x, origY: transform.y };
    },
    [transform]
  );
  const onMouseMove = useCallback((e) => {
    if (!dragState.current) return;
    const dx = e.clientX - dragState.current.startX;
    const dy = e.clientY - dragState.current.startY;
    setTransform((t) => ({ ...t, x: dragState.current.origX + dx, y: dragState.current.origY + dy }));
  }, []);
  const onMouseUp = useCallback(() => {
    dragState.current = null;
  }, []);

  const selected = selectedId ? byId.get(selectedId) : null;

  const nomeDe = (id) => (byId.get(id) ? byId.get(id).nome : null);

  return (
    <div
      style={{
        fontFamily: "'Iowan Old Style', 'Palatino Linotype', Georgia, serif",
        background: COLORS.bg,
        minHeight: "100vh",
        color: COLORS.ink,
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* ---------- Cabeçalho ---------- */}
      <header
        style={{
          padding: "20px 28px 14px",
          borderBottom: `1px solid ${COLORS.line}`,
          background: COLORS.bgPanel,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", flexWrap: "wrap", gap: 12 }}>
          <div>
            <h1 style={{ margin: 0, fontSize: 26, fontWeight: 600, letterSpacing: 0.2 }}>
              Memorial dos Brambillas
            </h1>
            <p style={{ margin: "4px 0 0", color: COLORS.inkSoft, fontSize: 14 }}>
              {pessoas.length} pessoas · 7 gerações · Busnago (Itália) → São Paulo
            </p>
          </div>

          <div style={{ position: "relative", minWidth: 260 }}>
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Buscar por nome…"
              style={{
                width: "100%",
                padding: "9px 14px",
                borderRadius: 6,
                border: `1px solid ${COLORS.lineDark}`,
                background: "#fff",
                fontFamily: "inherit",
                fontSize: 14,
                color: COLORS.ink,
                outline: "none",
              }}
            />
            {searchResults.length > 0 && (
              <div
                style={{
                  position: "absolute",
                  top: "110%",
                  left: 0,
                  right: 0,
                  background: "#fff",
                  border: `1px solid ${COLORS.line}`,
                  borderRadius: 6,
                  boxShadow: "0 6px 20px rgba(0,0,0,0.12)",
                  zIndex: 50,
                  maxHeight: 320,
                  overflowY: "auto",
                }}
              >
                {searchResults.map((r) => (
                  <div
                    key={r.id}
                    onClick={() => {
                      revealPath(r.id);
                      setQuery("");
                    }}
                    style={{
                      padding: "8px 14px",
                      cursor: "pointer",
                      fontSize: 13.5,
                      borderBottom: `1px solid ${COLORS.bg}`,
                      display: "flex",
                      justifyContent: "space-between",
                    }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = COLORS.bg)}
                    onMouseLeave={(e) => (e.currentTarget.style.background = "#fff")}
                  >
                    <span>{r.nome}</span>
                    <span style={{ color: COLORS.inkSoft, fontSize: 11.5 }}>ger. {r.geracao.toUpperCase()}</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          <button
            onClick={() => setShowConfig((s) => !s)}
            style={{
              padding: "9px 16px",
              borderRadius: 6,
              border: `1px solid ${COLORS.lineDark}`,
              background: showConfig ? COLORS.ink : COLORS.bgPanel,
              color: showConfig ? COLORS.bgPanel : COLORS.ink,
              fontFamily: "inherit",
              fontSize: 13.5,
              cursor: "pointer",
              whiteSpace: "nowrap",
            }}
          >
            ⚙ Layout
          </button>
        </div>

        {showConfig && (
          <LayoutConfigPanel
            layoutConfig={layoutConfig}
            setLayoutConfig={setLayoutConfig}
            onExpandAll={expandAll}
            onCollapseAll={collapseAll}
            colors={COLORS}
          />
        )}
      </header>

      {/* ---------- Corpo ---------- */}
      <div style={{ flex: 1, display: "flex", overflow: "hidden" }}>
        {/* Árvore */}
        <div
          ref={containerRef}
          onWheel={onWheel}
          onMouseDown={onMouseDown}
          onMouseMove={onMouseMove}
          onMouseUp={onMouseUp}
          onMouseLeave={onMouseUp}
          style={{
            flex: 1,
            overflow: "hidden",
            position: "relative",
            cursor: dragState.current ? "grabbing" : "grab",
            backgroundImage:
              "radial-gradient(circle, rgba(140,59,46,0.06) 1px, transparent 1px)",
            backgroundSize: "22px 22px",
          }}
        >
          <svg
            width="100%"
            height="100%"
            style={{ display: "block" }}
          >
            <g transform={`translate(${transform.x},${transform.y}) scale(${transform.k})`}>
              {/* Linhas de geração */}
              {generationLabels.map((g) => (
                <g key={g.idx}>
                  <text
                    x={-10}
                    y={g.y + NODE_H / 2}
                    textAnchor="end"
                    fontSize={12}
                    fill={COLORS.inkSoft}
                    fontStyle="italic"
                  >
                    {g.label}
                  </text>
                  <line
                    x1={0}
                    y1={g.y - 16}
                    x2={svgWidth}
                    y2={g.y - 16}
                    stroke={COLORS.line}
                    strokeDasharray="2,4"
                  />
                </g>
              ))}

              {/* Arestas pai->filho */}
              {edges.map((e, i) => {
                const from = positioned.get(e.from);
                const to = positioned.get(e.to);
                if (!from || !to) return null;
                const x1 = from.x + NODE_W / 2;
                const y1 = from.y + NODE_H;
                const x2 = to.x + NODE_W / 2;
                const y2 = to.y;
                const midY = (y1 + y2) / 2;
                return (
                  <path
                    key={i}
                    d={`M ${x1} ${y1} C ${x1} ${midY}, ${x2} ${midY}, ${x2} ${y2}`}
                    fill="none"
                    stroke={COLORS.lineDark}
                    strokeWidth={1.4}
                    opacity={0.55}
                  />
                );
              })}

              {/* Linhas de casamento (cônjuges lado a lado) */}
              {Array.from(positioned.entries()).map(([id, info]) => {
                if (info.isSpouse) return null;
                const person = info.person;
                return (person.conjuges || []).map((cid) => {
                  const cInfo = positioned.get(cid);
                  if (!cInfo) return null;
                  const x1 = info.x + NODE_W;
                  const x2 = cInfo.x;
                  const y = info.y + NODE_H / 2;
                  return (
                    <line
                      key={`${id}-${cid}`}
                      x1={x1}
                      y1={y}
                      x2={x2}
                      y2={y}
                      stroke={COLORS.gold}
                      strokeWidth={2}
                    />
                  );
                });
              })}

              {/* Nós */}
              {Array.from(positioned.entries()).map(([id, info]) => {
                const p = info.person;
                if (!p) return null;
                const hasChildren = (p.filhos_ids || []).length > 0;
                const isCollapsed = collapsed.has(id);
                const isSelected = selectedId === id;
                const cor = corPrincipal(p.status_dado);
                const isUsuario = id === "G-rodrigo-aroni-siquette";

                return (
                  <g
                    key={id}
                    transform={`translate(${info.x},${info.y})`}
                    style={{ cursor: "pointer" }}
                    onClick={() => setSelectedId(id)}
                  >
                    <rect
                      width={NODE_W}
                      height={NODE_H}
                      rx={7}
                      fill={info.isSpouse ? "#F7F2E7" : COLORS.bgPanel}
                      stroke={isSelected ? COLORS.accent : cor}
                      strokeWidth={isSelected ? 2.4 : isUsuario ? 2.4 : 1.4}
                      strokeDasharray={info.isSpouse ? "0" : "0"}
                    />
                    {isUsuario && (
                      <rect
                        width={NODE_W}
                        height={NODE_H}
                        rx={7}
                        fill="none"
                        stroke={COLORS.accent}
                        strokeWidth={1}
                        strokeDasharray="3,2"
                        transform="scale(1.06) translate(-5,-2)"
                      />
                    )}
                    <circle cx={12} cy={12} r={4} fill={cor} />
                    <text
                      x={NODE_W / 2}
                      y={26}
                      textAnchor="middle"
                      fontSize={12.5}
                      fontWeight={600}
                      fill={COLORS.ink}
                    >
                      {truncate(p.nome, 20)}
                    </text>
                    <text
                      x={NODE_W / 2}
                      y={42}
                      textAnchor="middle"
                      fontSize={10.5}
                      fill={COLORS.inkSoft}
                    >
                      {anosTexto(p)}
                    </text>
                    {hasChildren && (
                      <g
                        transform={`translate(${NODE_W / 2 - 9}, ${NODE_H - 4})`}
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleCollapse(id);
                        }}
                      >
                        <circle cx={9} cy={9} r={9} fill={COLORS.bgPanel} stroke={COLORS.lineDark} strokeWidth={1} />
                        <text x={9} y={13} textAnchor="middle" fontSize={12} fill={COLORS.ink}>
                          {isCollapsed ? "+" : "–"}
                        </text>
                      </g>
                    )}
                  </g>
                );
              })}
            </g>
          </svg>

          {/* Controles de zoom */}
          <div style={{ position: "absolute", bottom: 16, right: 16, display: "flex", flexDirection: "column", gap: 6 }}>
            <ZoomBtn onClick={() => setTransform((t) => ({ ...t, k: Math.min(2.2, t.k + 0.15) }))}>+</ZoomBtn>
            <ZoomBtn onClick={() => setTransform((t) => ({ ...t, k: Math.max(0.25, t.k - 0.15) }))}>–</ZoomBtn>
            <ZoomBtn onClick={() => setTransform({ x: 40, y: 40, k: 1 })} small>
              ⟲
            </ZoomBtn>
          </div>

          {/* Legenda */}
          <div
            style={{
              position: "absolute",
              bottom: 16,
              left: 16,
              background: COLORS.bgPanel,
              border: `1px solid ${COLORS.line}`,
              borderRadius: 8,
              padding: showLegend ? "12px 16px" : "6px 12px",
              fontSize: 12.5,
              boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
            }}
          >
            <div
              style={{ cursor: "pointer", fontWeight: 600, marginBottom: showLegend ? 8 : 0 }}
              onClick={() => setShowLegend((s) => !s)}
            >
              Legenda {showLegend ? "▾" : "▸"}
            </div>
            {showLegend && (
              <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {Object.entries(STATUS_META).map(([key, meta]) => (
                  <div key={key} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                    <span
                      style={{
                        width: 9,
                        height: 9,
                        borderRadius: "50%",
                        background: meta.cor,
                        display: "inline-block",
                      }}
                    />
                    <span style={{ color: COLORS.inkSoft }}>{meta.label}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Painel de detalhes */}
        <aside
          style={{
            width: selected ? 340 : 0,
            transition: "width 0.2s ease",
            overflow: "hidden",
            borderLeft: selected ? `1px solid ${COLORS.line}` : "none",
            background: COLORS.bgPanel,
          }}
        >
          {selected && <DetailPanel person={selected} nomeDe={nomeDe} onClose={() => setSelectedId(null)} onNavigate={revealPath} />}
        </aside>
      </div>
    </div>
  );
}

function LayoutConfigPanel({ layoutConfig, setLayoutConfig, onExpandAll, onCollapseAll, colors }) {
  const sliders = [
    { key: "nodeW", label: "Largura do nó", min: 100, max: 280, step: 4 },
    { key: "hGap", label: "Espaçamento horizontal (eixo X)", min: 4, max: 120, step: 2 },
    { key: "vGap", label: "Espaçamento vertical entre gerações (eixo Y)", min: 60, max: 240, step: 5 },
    { key: "coupleGap", label: "Espaço entre cônjuges", min: 0, max: 60, step: 2 },
  ];

  return (
    <div
      style={{
        marginTop: 14,
        padding: "16px 18px",
        background: "#fff",
        border: `1px solid ${colors.line}`,
        borderRadius: 8,
        display: "flex",
        flexWrap: "wrap",
        gap: 24,
        alignItems: "flex-end",
      }}
    >
      {sliders.map((s) => (
        <div key={s.key} style={{ minWidth: 200 }}>
          <label style={{ fontSize: 12, color: colors.inkSoft, display: "block", marginBottom: 4 }}>
            {s.label}: <strong style={{ color: colors.ink }}>{layoutConfig[s.key]}px</strong>
          </label>
          <input
            type="range"
            min={s.min}
            max={s.max}
            step={s.step}
            value={layoutConfig[s.key]}
            onChange={(e) =>
              setLayoutConfig((prev) => ({ ...prev, [s.key]: Number(e.target.value) }))
            }
            style={{ width: "100%" }}
          />
        </div>
      ))}

      <div style={{ display: "flex", gap: 8 }}>
        <button
          onClick={onExpandAll}
          style={{
            padding: "8px 14px",
            borderRadius: 6,
            border: `1px solid ${colors.lineDark}`,
            background: colors.bgPanel,
            fontFamily: "inherit",
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          Abrir todos os nós
        </button>
        <button
          onClick={onCollapseAll}
          style={{
            padding: "8px 14px",
            borderRadius: 6,
            border: `1px solid ${colors.lineDark}`,
            background: colors.bgPanel,
            fontFamily: "inherit",
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          Fechar todos os nós
        </button>
      </div>
    </div>
  );
}

function ZoomBtn({ children, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        width: 32,
        height: 32,
        borderRadius: 6,
        border: `1px solid ${COLORS.lineDark}`,
        background: COLORS.bgPanel,
        color: COLORS.ink,
        fontSize: 16,
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {children}
    </button>
  );
}

function DetailPanel({ person, nomeDe, onClose, onNavigate }) {
  const nasc = person.nascimento || {};
  const fal = person.falecimento || {};

  return (
    <div style={{ padding: "20px 20px 24px", overflowY: "auto", height: "100%" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <h2 style={{ margin: 0, fontSize: 18, lineHeight: 1.3 }}>{person.nome}</h2>
        <button
          onClick={onClose}
          style={{ border: "none", background: "none", fontSize: 18, cursor: "pointer", color: COLORS.inkSoft }}
        >
          ×
        </button>
      </div>
      <div style={{ fontSize: 12.5, color: COLORS.inkSoft, marginTop: 2 }}>Geração {person.geracao.toUpperCase()}</div>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 12 }}>
        {(person.status_dado || []).map((s) => (
          <span
            key={s}
            style={{
              fontSize: 11,
              padding: "3px 9px",
              borderRadius: 20,
              background: (STATUS_META[s]?.cor || "#999") + "22",
              color: STATUS_META[s]?.cor || "#999",
              border: `1px solid ${(STATUS_META[s]?.cor || "#999")}55`,
            }}
          >
            {STATUS_META[s]?.label || s}
          </span>
        ))}
      </div>

      <Field label="Nascimento" value={formatEvento(nasc)} />
      <Field label="Falecimento" value={formatEvento(fal)} />

      {person.pai_id && <Field label="Pai" value={nomeDe(person.pai_id)} onClick={() => onNavigate(person.pai_id)} />}
      {person.mae_id && <Field label="Mãe" value={nomeDe(person.mae_id)} onClick={() => onNavigate(person.mae_id)} />}
      {(person.conjuges || []).length > 0 && (
        <Field
          label="Cônjuge(s)"
          value={person.conjuges.map(nomeDe).filter(Boolean).join(", ")}
        />
      )}
      {(person.filhos_ids || []).length > 0 && (
        <Field label={`Filhos (${person.filhos_ids.length})`} value={person.filhos_ids.map(nomeDe).filter(Boolean).join(", ")} />
      )}

      {person.observacoes && (
        <div style={{ marginTop: 16 }}>
          <div style={{ fontSize: 11.5, textTransform: "none", color: COLORS.inkSoft, marginBottom: 4 }}>Observações</div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{person.observacoes}</div>
        </div>
      )}

      {(person.fontes || []).length > 0 && (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontSize: 11.5, color: COLORS.inkSoft, marginBottom: 4 }}>Fontes</div>
          <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12.5, lineHeight: 1.6 }}>
            {person.fontes.map((f, i) => (
              <li key={i}>{f}</li>
            ))}
          </ul>
        </div>
      )}

      <div style={{ marginTop: 20, paddingTop: 14, borderTop: `1px solid ${COLORS.line}` }}>
        <div style={{ fontSize: 11.5, color: COLORS.inkSoft, marginBottom: 6 }}>
          Comentários {person.comentarios && person.comentarios.length > 0 ? `(${person.comentarios.length})` : ""}
        </div>
        {(person.comentarios || []).length === 0 && (
          <div style={{ fontSize: 12.5, color: COLORS.inkSoft, fontStyle: "italic" }}>
            Nenhum comentário ainda. (Neste protótipo, comentários não são salvos — a versão web permitirá adicionar apontamentos aqui.)
          </div>
        )}
      </div>
    </div>
  );
}

function Field({ label, value, onClick }) {
  if (!value) return null;
  return (
    <div style={{ marginTop: 10 }}>
      <div style={{ fontSize: 11.5, color: COLORS.inkSoft }}>{label}</div>
      <div
        style={{
          fontSize: 13.5,
          cursor: onClick ? "pointer" : "default",
          color: onClick ? COLORS.accent : COLORS.ink,
          textDecoration: onClick ? "underline" : "none",
        }}
        onClick={onClick}
      >
        {value}
      </div>
    </div>
  );
}

function truncate(str, n) {
  if (!str) return "";
  return str.length > n ? str.slice(0, n - 1) + "…" : str;
}

function anosTexto(p) {
  const n = p.nascimento || {};
  const f = p.falecimento || {};
  const nascAno = extractYear(n.data || n.data_estimada);
  const falAno = extractYear(f.data);
  if (nascAno && falAno) return `${nascAno} – ${falAno}`;
  if (nascAno) return `n. ${nascAno}`;
  if (falAno) return `† ${falAno}`;
  return "—";
}

function extractYear(str) {
  if (!str) return null;
  const m = String(str).match(/(\d{4})/);
  return m ? m[1] : null;
}

function formatEvento(ev) {
  if (!ev) return null;
  const partes = [];
  if (ev.data) partes.push(ev.data);
  else if (ev.data_estimada) partes.push(ev.data_estimada);
  if (ev.local) partes.push(ev.local);
  if (partes.length === 0) return null;
  return partes.join(" — ");
}

export default App;
